function sync(){let dirty=false,at=now();for(const id of ["material","crystal"]){if(!S.layout[id])continue;const b=S.buildings[id],p=production(id),elapsed=Math.max(0,at-(+b.lastAt||at)),network=id==="material"?powered(id):(powered(id)&&hasLink("material","crystal")&&hasLink("crystal","depot"));if(!network){b.status=powered(id)?"blocked":"offline";b.lastAt=at;continue;}if(elapsed>=1000){b.stored=Math.min(p.cap,(+b.stored||0)+elapsed/3600000*p.rate);b.lastAt=at;b.status=b.stored>=p.cap?"collectable":"producing";dirty=true;}}if(S.craft&&S.craft.status==="crafting"&&at>=S.craft.endAt){S.craft.status="complete";S.buildings.manufacturing.status="collectable";dirty=true;}if(dirty)save();}
