function upgrade(id){const b=S.buildings[id],d=DEF[id],n=upgradeCost(id);if(d.req&&S.buildings.command.level<d.req)return note(T("需要指挥中心 Lv."+d.req,"Requires Command Center Lv."+d.req));if(b.level>=d.max)return note(T("已达到当前等级上限","Current level cap reached"));if(S.screws<n)return note(T("螺丝不足","Not enough screws"));S.screws-=n;b.level++;note(T("升级成功","Upgrade complete"));}
