function sync7(){const at=now(),hub=S.instances.find(x=>x.type==="command"),order=["material","crusher","synth","forge","mint"];for(const type of order)for(const v of S.instances.filter(x=>x.type===type)){const cycles=Math.min(120,Math.floor((at-v.lastAt)/5000));if(cycles<1)continue;v.lastAt+=cycles*5000;if(!powered7(v)){v.status="offline";continue;}let made=0;for(let i=0;i<cycles;i++){
    if(type==="material"){if(!hub||!routeReachable7(v.iid,hub.iid)){v.status="awaiting hub return";break;}S.materials+=2;made++;continue;}
    const inbound=hub&&routeReachable7(hub.iid,v.iid),outbound=hub&&routeReachable7(v.iid,hub.iid);if(!inbound||!outbound){v.status="logistics incomplete";break;}
    if(type==="crusher"&&S.rawOre>=3){S.rawOre-=3;S.materialStock.powder+=2;made++;}
    else if(type==="synth"&&S.materialStock.powder>=2&&S.materials>=2){S.materialStock.powder-=2;S.materials-=2;S.materialStock.composite++;made++;}
    else if(type==="forge"&&S.materialStock.composite>=1){S.materialStock.composite--;S.materialStock.ingot++;made++;}
    else if(type==="mint"&&S.materialStock.ingot>=1&&outbound){S.materialStock.ingot--;S.coins+=12;made++;}
    else{v.status="waiting";break;}
  }if(made)v.status="producing";}persistV7();}
