function move7(x,y){if(!drag.active)return;const dx=x-drag.startX,dy=y-drag.startY;if(Math.hypot(dx,dy)>4)drag.moved=true;S.camera.x=drag.camX-dx/(GRID.cw*S.zoom);S.camera.y=drag.camY-dy/(GRID.ch*S.zoom);clamp7();}
function up7(){if(drag.active){drag.active=false;save();}}
function wheel7(delta,x,y){if(S.page!=="baseBuild")return false;if(x>=878&&x<=1088&&y>=130&&y<=588){S.catalogScroll=Math.max(0,Math.min(BUILD_ORDER.length*46-340,S.catalogScroll+Math.sign(delta)*44));save();return true;}if(x>=VIEW7.x&&x<=VIEW7.x+VIEW7.w&&y>=VIEW7.y&&y<=VIEW7.y+VIEW7.h){const before=world7(x,y);S.zoom=Math.max(.55,Math.min(1.6,S.zoom*(delta>0?.9:1.1)));const after=world7(x,y);S.camera.x+=before.x-after.x;S.camera.y+=before.y-after.y;clamp7();save();return true;}return false;}
function grantBattleResources7(pack){let total=0;for(const [k,n0] of Object.entries(pack||{})){const n=Math.max(0,Math.floor(+n0||0));if(!n)continue;total+=n;if(k==="rawOre"||k==="crystal")S.rawOre+=n;else if(k==="materials")S.materials+=n;else if(k==="scrap")S.materialStock.scrap+=n;else if(k==="fiber")S.materialStock.fiber+=n;}save();return total;}
function grantScrews7(amount){const n=Math.max(0,Math.floor(+amount||0));if(!n)return 0;S.screws+=n;save();return n;}
