function resourceName8(k){const n={rawOre:["晶体原矿","Raw Crystal"],materials:["基础原料","Base Materials"],wood:["荒地木材","Wasteland Timber"],resin:["晶化树脂","Crystal Resin"],stone:["结构岩","Structural Stone"],herbs:["复生植株","Revival Herb"],scrap:["废墟合金","Ruin Alloy"],fiber:["合成纤维","Synth Fiber"],powder:["晶体粉末","Crystal Powder"],composite:["稳定复材","Stable Composite"],treatedWood:["稳定木材","Stabilized Timber"],alloyPlate:["废区合金板","Ruin Alloy Plate"],crystalCable:["晶体线缆","Crystal Cable"],circuitBoard:["控制电路板","Control Circuit"],opticalLens:["晶体光学镜","Crystal Optics"],powerCell:["工业电芯","Power Cell"],logisticsUnit:["物流控制单元","Logistics Controller"],defenseCore:["防御运算核心","Defense Processor"]};return T(...(n[k]||[k,k]));}
