function spawnRaidGroup8(count){const q=grid7(),targets=S.instances.filter(v=>v.hp>0);if(!targets.length)return[];const out=[];for(let i=0;i<count;i++){const side=i%4,p=side===0?{x:-1,y:(i*7)%q.rows}:side===1?{x:q.cols+1,y:(i*5)%q.rows}:side===2?{x:(i*7)%q.cols,y:-1}:{x:(i*5)%q.cols,y:q.rows+1},hp=65+S.raidWave*18;out.push({x:p.x,y:p.y,hp,maxHp:hp,speed:.32+Math.min(.25,S.raidWave*.012),target:targets[(i*3+S.raidWave)%targets.length].iid,attackAt:0});}return out;}
