function updateRaid8(){
 const at=now(),dt=Math.max(0,Math.min(.08,(at-raidTick8)/1000));raidTick8=at;
 raidShotFx8=raidShotFx8.filter(f=>at-f.at<360);
 if(!S.raid&&at>=S.nextRaidAt)startRaid8();if(!S.raid)return;
 if(at>=S.raid.endsAt){finishRaid8();return;}
 let alive=S.raid.enemies.filter(e=>e.hp>0);
 if(!alive.length&&!S.raid.reinforced&&S.raid.endsAt-at>5000){S.raid.enemies.push(...spawnRaidGroup8(Math.min(10,3+S.raidWave)));S.raid.reinforced=true;alive=S.raid.enemies.filter(e=>e.hp>0);}
 for(const tower of S.instances.filter(v=>["turret","slowTower","artillery"].includes(v.type)&&v.hp>0&&powered7(v))){
  const d=DEF[tower.type],range=(d.range||4)*(tower.type==="slowTower"&&hasSkill6("stasisNet")?1.25:1),targets=alive.filter(e=>e.hp>0&&Math.hypot(e.x-(tower.x+.5),e.y-(tower.y+.5))<=range).sort((a,b)=>Math.hypot(a.x-tower.x,a.y-tower.y)-Math.hypot(b.x-tower.x,b.y-tower.y));
  if(!targets.length)continue;
  const interval=(tower.type==="turret"?420:tower.type==="slowTower"?760:1450)*(hasSkill6("targeting")?.85:1);
  if(at-(tower.lastShotAt8||0)<Math.max(180,interval-tower.level*22))continue;
  tower.lastShotAt8=at;const primary=targets[0],damage=Math.round((d.attack||10)*(1+tower.level*.18)*(hasSkill6("defenseCore")?1.15:1));
  primary.hp=Math.max(0,primary.hp-damage);raidShotFx8.push({at,fromX:tower.x+.5,fromY:tower.y+.5,toX:primary.x,toY:primary.y,damage,type:tower.type});
  if(primary.hp<=0){S.raid.kills=(S.raid.kills||0)+1;primary.defeatedAt=at;}
  if(tower.type==="artillery")for(const e of targets.slice(1,hasSkill6("counterBattery")?6:4)){const splash=Math.round(damage*(hasSkill6("counterBattery")?.62:.45));e.hp=Math.max(0,e.hp-splash);if(e.hp<=0&&!e.defeatedAt){e.defeatedAt=at;S.raid.kills=(S.raid.kills||0)+1;}}
 }
 for(const e of alive){if(e.hp<=0)continue;let v=instance7(e.target);if(!v||v.hp<=0){v=S.instances.filter(x=>x.hp>0).sort((a,b)=>a.type==="command"?-1:b.type==="command"?1:0)[0];if(!v)continue;e.target=v.iid;}let slow=1;for(const t of S.instances.filter(x=>x.type==="slowTower"&&powered7(x))){if(Math.hypot(e.x-t.x,e.y-t.y)<=(DEF.slowTower.range||4)*(hasSkill6("stasisNet")?1.25:1)){slow=hasSkill6("stasisNet")?.42:.58;break;}}const tx=v.x+DEF[v.type].w/2,ty=v.y+DEF[v.type].h/2,dx=tx-e.x,dy=ty-e.y,d=Math.hypot(dx,dy),l=d||1;if(d>.45){e.x+=dx/l*e.speed*slow*dt;e.y+=dy/l*e.speed*slow*dt;}else if(at-(e.attackAt||0)>900){e.attackAt=at;v.hp=Math.max(0,v.hp-(13+S.raidWave*2)*(hasSkill6("barrier")?.8:1));if(v.hp<=0)v.status="abnormal";}}
 if(at-(S.raid.lastSavedAt||0)>1500){S.raid.lastSavedAt=at;save();}
}
